declare global{interface Window{studioGrokConnection?:{connected:boolean;pending:boolean;offline:boolean};ProviderRecovery?:{mount:(host:HTMLElement,options:any)=>void;classify:(message:string,model?:string,kind?:string)=>{provider:string;kind:string};check:(provider:string)=>Promise<boolean>}}}
export function ImageRecovery({message,model,kind,retry,disabled=false}:{message:string;model?:string;kind?:string;retry?:()=>Promise<void>;disabled?:boolean}){const host=useRef<HTMLDivElement>(null),action=useRef(retry);action.current=retry;useEffect(()=>{if(host.current)window.ProviderRecovery?.mount(host.current,{message,model,kind,disabled,retry:retry?()=>action.current?.():undefined});},[message,model,kind,disabled,!!retry]);return <div ref={host} hidden/>;}
function GenerationError({view,retry,disabled,model}:{view:any;retry?:()=>Promise<void>;disabled?:boolean;model?:string}){const provider=/codex/i.test(view.error)?'ChatGPT · Image 2':/xai|grok/i.test(view.error)?'Grok Imagine':'';return <div className="wb-error">{provider&&<strong>{provider} request</strong>}<p role="alert">{view.error}</p><ImageRecovery message={view.error} model={view.error_model} kind={view.error_kind} retry={retry?async()=>{if(model&&view.error_model&&model!==view.error_model)throw Error('Select the failed request’s original image connection before retrying.');await retry();}:undefined} disabled={disabled}/><small>Completed candidates are kept. Changing the connection does not retry this request.</small></div>;}
