 const live=useRef<any>({});live.current={world,answers,guide,jobs,plan,dirty,planDirty};const savingRef=useRef<Promise<any>|null>(null),mounted=useRef(true),guard=useRef(false);
 const draftKey='imagine-world-v2-'+production.id;
 const latest=jobs.filter(j=>j.status==='done').at(-1)||jobs.at(-1),current=workshop?.job||latest,pending=jobs.some(j=>j.status==='pending'),rendering=workshop?.batches?.some((b:any)=>b.status==='pending');
 async function loadWorkshop(){const w=await service('filmmaking/worlds/'+production.id+'/workshop');if(mounted.current)setWorkshop(w);return w;}
 async function load(){const [w,j]=await Promise.all([service('filmmaking/worlds/'+production.id),service<any[]>('filmmaking/worlds/'+production.id+'/jobs')]);if(!mounted.current)return;setWorld(w);setJobs(j);const last=j.filter((x:any)=>x.status==='done').at(-1);if(j.at(-1)?.status==='error')setError(j.at(-1).error);if(last){setPlan(clone(last.applied_plan||last.result));if(last.workshop_started)await loadWorkshop();}return {w,j};}
 useEffect(()=>{mounted.current=true;load().then(result=>{if(!result)return;const {w,j}=result;let recovered:any=null;try{recovered=JSON.parse(sessionStorage.getItem(draftKey)||'null');}catch{}if(recovered){setAnswers(recovered.answers);setGuide(recovered.guide);setDirty(true);if(recovered.plan&&j.filter((x:any)=>x.status==='done').at(-1)?.id===recovered.job_id){setPlan(recovered.plan);setPlanDirty(true);}if(recovered.revision!==w.revision){guard.current=true;setError('A newer story was saved elsewhere. Download your draft before loading the saved version.');setWorld({...w,revision:recovered.revision});}}else{setAnswers(w.answers);setGuide(normalizeGuide(w.guide));}const saved=Number(sessionStorage.getItem(draftKey+'-stage')||0);setStage(j.filter((x:any)=>x.status==='done').at(-1)?.workshop_started?Math.min(2,saved):0);if(!sessionStorage.getItem(draftKey+'-page')&&j.some((x:any)=>x.status==='done'))setPage(5);}).catch(e=>setError(e.message));return()=>{mounted.current=false;};},[production.id]);
