 useEffect(()=>{const update=(event:Event)=>setDetailDirty((event as CustomEvent<boolean>).detail);window.addEventListener('studio-world-details',update);return()=>window.removeEventListener('studio-world-details',update);},[]);
 async function save(){if(savingRef.current){await savingRef.current;if(live.current.dirty||live.current.planDirty)return save();return live.current.world;}const action=async()=>{let l=live.current;if(!l.world)return;if(guard.current)throw Error('Load the saved story before saving this recovered draft.');setSaving(true);try{if(l.dirty){const w=await service('filmmaking/worlds/'+production.id,'PUT',{expected_revision:l.world.revision,answers:l.answers,guide:l.guide});if(mounted.current){setWorld(w);const unchanged=JSON.stringify(live.current.answers)===JSON.stringify(l.answers)&&JSON.stringify(live.current.guide)===JSON.stringify(l.guide);setDirty(!unchanged);live.current={...live.current,world:w,dirty:!unchanged};}}l=live.current;if(l.planDirty&&!l.jobs.filter((x:any)=>x.status==='done').at(-1)?.applied){const old=l.plan;const j=await service('filmmaking/jobs/'+l.jobs.filter((x:any)=>x.status==='done').at(-1).id,'PUT',{expected_revision:l.jobs.filter((x:any)=>x.status==='done').at(-1).revision,result:l.plan});const next=l.jobs.map((x:any)=>x.id===j.id?j:x);setJobs(next);const unchanged=JSON.stringify(live.current.plan)===JSON.stringify(old);setPlanDirty(!unchanged);live.current={...live.current,jobs:next,planDirty:!unchanged};}if(!live.current.dirty&&!live.current.planDirty)sessionStorage.removeItem(draftKey);return live.current.world;}finally{if(mounted.current)setSaving(false);}};const promise=action();savingRef.current=promise;try{return await promise;}finally{savingRef.current=null;}}
 useAgentEditor('world-book',{capture:()=>world?{id:world.id,revision:world.revision,dirty:dirty||planDirty||guard.current,data:{answers,guide,plan,provider,model}}:null,save:async()=>{if(busy||pending)throw Error('Storybook is busy.');await save();},reload:async()=>{if(busy||pending)throw Error('Storybook is busy.');const result=await load();if(!result)return;setAnswers(result.w.answers);setGuide(normalizeGuide(result.w.guide));setDirty(false);setPlanDirty(false);guard.current=false;sessionStorage.removeItem(draftKey);}});
