 async function openVisuals(){await save();const j=live.current.jobs.filter((x:any)=>x.status==='done').at(-1);const w=await service('filmmaking/worlds/'+production.id+'/workshop','POST',{job_id:j.id,expected_revision:j.revision,model});setWorkshop(w);const saved=await service('filmmaking/worlds/'+production.id);setWorld(saved);setGuide(normalizeGuide(saved.guide));setJobs(js=>js.map(x=>x.id===w.job.id?w.job:x));setStage(1);}
 async function generate(views:any[],count=1,prompt?:string,instruction?:string){await window.studioFilmFlush?.();await prepare();const ready=await workshopPrompts(views,model,prompt,instruction,instruction!==undefined);await loadWorkshop();if(!ready)return;const requests=views.flatMap(v=>Array.from({length:count},()=>({view_id:v.id,expected_revision:v.revision,...(prompt?{prompt}:{})})));await service('filmmaking/worlds/'+production.id+'/generate','POST',{job_id:workshop.job.id,model,approved:true,requests},crypto.randomUUID());await loadWorkshop();}
 const entities=(workshop?.entities||[]).filter((e:any)=>stage===1?e.category==='Character':e.category!=='Character'),entity=entities.find((e:any)=>e.id===selected)||entities[0];
